class PointCreationView {
  #element = null;
  getTemplate() {
    return createPointCreationTemplate();
  }

  getElement() {
    if(this.#element === null) {
      const template = this.getTemplate();
      this.#element = createElement(template);
    }
    return this.#element;
  }
}

export default PointCreationView;
